def find_minimal_edit(s_in, s_out):
    """Find the minimal edit - what needs to change from s_in to s_out"""
    # Simple approach: find first and last differing positions
    min_pos = None
    max_pos = -1

    for i in range(min(len(s_in), len(s_out))):
        if s_in[i] != s_out[i]:
            if min_pos is None:
                min_pos = i
            max_pos = i

    # If no differences found in shared length, check for length differences
    if min_pos is None:
        if len(s_in) != len(s_out):
            min_pos = min(len(s_in), len(s_out))
            max_pos = max(len(s_in), len(s_out)) - 1
        else:
            return None, None, None

    # Get the substring that needs to change
    if len(s_in) > len(s_out):
        # Deletion case
        old_sub = s_in[min_pos:max_pos+1]
        new_sub = s_out[min_pos:min_pos+len(old_sub)]
    elif len(s_in) < len(s_out):
        # Insertion case  
        old_sub = s_in[min_pos:]
        new_sub = s_out[min_pos:min_pos+len(old_sub)]
    else:
        # Same length case
        old_sub = s_in[min_pos:max_pos+1]
        new_sub = s_out[min_pos:max_pos+1]

    return old_sub, new_sub, min_pos

